// A photo descriptor and crop are copied from the opened Lens photograph.
export function photoStudySource(photo,photoView){
 try{return {v:1,model:'photo-study-v1',id:'onion-photo-study',title:'Onion photo study',context:'The librarian needs a record for the next keeper. Choose a few shapes or borders you can point to in the photograph. Draw them beside it, then leave labels or a caption for your reader.',notice:'Your drawing records what you chose to show. It is not a live microscope view or a measured map. Paper coordinates only place marks; they are not millimeters. A label marked ‘I notice’ is your description, not an answer checked by the game.',returnQuestion:'Compare your study with the photograph and a Cell Studio illustration. Which lines describe something you can point to in the photo? Could a difference come from a different kind of cell, from what the photograph shows, or from symbols chosen to explain an idea? What would another image or a real slide help you check?',photo:structuredClone(photo),photoView:structuredClone(photoView),paper:{width:1000,height:750},teaching:[
 'Look first. Choose a small patch and follow a few visible borders. You do not need to fill the paper.',
 'Use clear lines to show what you can point to, rather than copying every Cell Studio symbol from memory.',
 'For our made-up box example: ‘I notice a long edge’ describes a visible line; ‘My idea: it might be a wall’ is an interpretation; ‘My question: what is on the other side?’ asks for more evidence. This box is not from the onion photograph.',
 'Help your reader find the feature with a numbered pointer. A caption can say which patch you drew and what you are unsure about. One onion photograph does not show every kind of cell.'
 ],example:{paper:{width:1000,height:750},strokes:[{id:'s1',points:'200,200 700,200 700,500 200,500 200,200'}],labels:[{id:'l1',kind:'notice',text:'a long edge',at:{x:450,y:200}},{id:'l2',kind:'idea',text:'it might be a wall',at:{x:700,y:350}},{id:'l3',kind:'question',text:'what is on the other side?',at:{x:450,y:500}}],caption:'An invented box, not an onion cell.'}};}catch{return null;}
}
